--region 通用方法

---@generic T
---@class CommonWeightData
---@field weight int
---@field data T @ 可自定义内容

---@generic T
---@param weightDataList CommonWeightData[] @ <T>
---@param totalWeight int? @ 空则通过 weightDataList 计算
---@return T, int @ data, index
function CommonViewModel.GetRandomWeightData(weightDataList, totalWeight)
    if not weightDataList or #weightDataList == 0 then
        return nil, 0
    end

    if not totalWeight then
        totalWeight = 0
        for _, wData in ipairs(weightDataList) do
            totalWeight = totalWeight + wData.weight
        end
    end
    
    local randomNum = math.random(0, totalWeight)
    local curWeight = 0
    for i, wData in ipairs(weightDataList) do
        curWeight = curWeight + wData.weight
        if randomNum <= curWeight then
            return wData.data, i
        end
    end
    
    Global.LogError("Weight data wrong. Return first data.")
    return weightDataList[1].data, 1
end

--- 从容器中选出部分值
---@generic TData
---@param container TData[]
---@param fSelector fun(data:TData):boolean
---@return TData[]
function CommonViewModel.FSelect(container, fSelector)
    local list = {}
    for _, data in pairs(container) do
        if fSelector(data) then
            table.insert(list, data)
        end
    end
    return list
end

