--- 通用的返回相关按钮逻辑
---@param uid int @ 界面 uid
---@param backBtn UnityEngine.GameObject?
---@param homeBtn UnityEngine.GameObject?
---@param helpBtn UnityEngine.GameObject?
---@param tutorialId int? @ 帮助按钮显示内容
function CommonViewModel.CommonReturnBtns(backBtn, homeBtn, helpBtn, tutorialId)
    if not Global.IsNil(backBtn) then
        UIEvent.LuaClick(backBtn, function()
            MgrUI.GoBack()
        end)
    end

    if not Global.IsNil(homeBtn) then
        UIEvent.LuaClick(homeBtn, function() 
            MgrUI.GoBackTo(UID.Home_UI)
        end)
    end

    if not Global.IsNil(helpBtn) then
        UIEvent.LuaClick(helpBtn, function()
            if tutorialId and tutorialId ~= 0 then
                ActiveTutorialControl.OpenGuide(tutorialId)
            else
                Global.PopTip("Click help", nil, true)
            end
        end)
    end
end

--- 通用的返回事件方法
---@param uid int @ 界面uid
function CommonViewModel.CommonBackKey(uid)
    if MgrUI.IsPopOpen() or not MgrUI.IsShow(uid) then
        return
    end
    MgrUI.GoBack()
end

