--- 在指定 Root 下创建 NpcSpine
---@param npcId int @ 用于Charactercoordinates表确定坐标及加载角色预制体。
---@param spineRoot UnityEngine.GameObject
---@param callback fun(spineObj:UnityEngine.GameObject)
function CommonViewModel.CreateNpcSpine(npcId, spineRoot, callback)
    if npcId == 0 then
        return
    end
    if Global.IsNil(spineRoot) then
        Global.LogError("Create npc spine failed. SpineRoot does not exist.")
        return
    end
    
    local coordStr = CheckTable(CharactercoordinatesLocalData.tab[npcId]).coordinate10
    local x = 0
    local y = 0
    local scale = 1
    if not Global.IsStrNil(coordStr) then
        local splitStr1 = string.split(coordStr, ";")
        local splitStr2 = string.split(splitStr1[1], ",")
        x = tonumber(splitStr2[1]) or 0
        y = tonumber(splitStr2[2]) or 0
        scale = tonumber(splitStr1[2]) or 1
        --local turn = tonumber(splitStr1[3])
    end
    ---@param obj UnityEngine.GameObject
    MgrRes.LoadWatch3DSpineInUI(spineRoot, npcId, x, y, scale, "idle", function(obj)
        -- UI 层
        obj.layer = 5
        if callback then
            callback(obj)
        end
    end)
end

