--- 播放 npc 语音
---@param npcId int @ 用于ActorLines表检索group
---@param readType ActorLinesReadType @ 用于ActorLines表检索readType
---@param spineObj UnityEngine.GameObject @ 播放角色语音动画
---@param txtComp TMPro.TextMeshProUGUI @ 显示语音台词
---@param wordRoot UnityEngine.GameObject @ 显示台词时显隐，空则为 txtComp 对象
---@param timerName string? @ 监听结束计时器，空则不开启计时器。通过 MgrTimer.Cancel 取消
---@param fOnVoiceEnd fun()? @ 监听到语音结束时的回调。空则执行默认的逻辑——隐藏 wordRoot。该方法内不需要手动取消监听。
function CommonViewModel.PlayNpcVoice(npcId, readType, spineObj, txtComp, wordRoot, timerName, fOnVoiceEnd)
    local lineId = CommonViewModel.GetRandomActionLine(npcId, readType)
    local lData = ActorVoiceLocalData.tab[CheckNumber(lineId)]
    if not lData then
        return
    end
    
    local animationName = lData[6]
    local audioName = lData[13]
    local content = lData[7]

    if not Global.IsConfigNil(animationName) and not Global.IsNil(spineObj) then
        CMgrSpine.Instance:SetSpineAnimation(spineObj, animationName, true)
    end
    if not Global.IsConfigNil(content) and not Global.IsNil(txtComp) then
        if Global.IsNil(wordRoot) then
            wordRoot = txtComp.gameObject
        end
        txtComp.text = content
        wordRoot:SetActive(true)
    end
    
    if not Global.IsConfigNil(audioName) then
        local npcIdStr = tostring(npcId)
        MgrSound.PlayRole(audioName, nil, nil, false, 0, 0, npcIdStr)
        if not Global.IsStrNil(timerName) then
            MgrTimer.AddRepeat(timerName, 0.2, function()
                if not MgrSound.CheckRoleStatus(npcIdStr) then
                    return
                end
                MgrTimer.Cancel(timerName)
                if fOnVoiceEnd then
                    fOnVoiceEnd()
                else
                    if not Global.IsNil(wordRoot) then
                        wordRoot:SetActive(false)
                    end
                end
            end, -1, nil)
        end
    end
end

