--- 获取 Npc 某类台词列表
---@param npcId int @ 用于ActorLines表检索group
---@param readType ActorLinesReadType @ 用于ActorLines表检索readType
---@return CommonWeightData[], int @ data为台词id, 总权重
function CommonViewModel.GetNpcActorLines(npcId, readType)
    ---@type CommonWeightData[]
    local list = {}
    local totalWeight = 0
    
    -- TODO(Arno) 每次都搜一万多行数据？考虑是否需要缓存为字典
    for id, line in pairs(ActorLinesLocalData.tab) do
        if line[2] == npcId and line[3] == readType then
            -- TODO(Arno) 暂不考虑条件，若要添加，见 TableToObject.GetTargetWeight
            ---@type CommonWeightData<int>
            local wData = {
                -- 固定值
                weight = 10,
                data = id,
            }
            totalWeight = totalWeight + wData.weight
            table.insert(list, wData)
        end
    end
    
    return list, totalWeight
end

