---@param readType ActorLinesReadType @ 用于ActorLines表检索readType
---@return int @ ActorLines.id
function CommonViewModel.GetRandomActionLine(npcId, readType)
    local wDataList, totalWeight = CommonViewModel.GetNpcActorLines(npcId, readType)
    local lineId, _ = CommonViewModel.GetRandomWeightData(wDataList, totalWeight)
    return lineId or 0
end

--- 返回源数据，请勿修改
--- key 只是顺序插入的索引，无意义
---@param group
---@return table[] @ ActorLinesLocalData[]
function CommonViewModel.GetActorLinesByGroup(group)
    local list = ActorLinesGroupMap[group]
    if list then
        return list
    end

    list = CommonViewModel.FSelect(ActorLinesLocalData.tab, function(data)
        return data[2] == group
    end)
    ActorLinesGroupMap[group] = list
    return list
end

